import React from "react";
import "./Sidebar.css";

const Sidebar = () => {
  return (
    <aside className="sidebar">

      <h2>PG Admin</h2>

      <ul>

        <li>Dashboard</li>

        <li>Resident Management</li>

        <li>Room Management</li>

        <li>Bed Allocation</li>

        <li>Rent Management</li>

        <li>Bill Management</li>

        <li>Payment Tracking</li>

        <li>Complaint Management</li>

        <li>Notifications</li>

        <li>Reports</li>

        <li>Profile</li>

      </ul>

    </aside>
  );
};

export default Sidebar;
